import os
import json
import time
import hmac
import hashlib
import tempfile
import secrets
import stat as stat_module
from pathlib import Path
from typing import Optional, Dict, Any

# Configuration
SESSION_DIR = os.environ.get('SESSION_DIR', '/tmp/sessions')
SESSION_SECRET = os.environ.get('SESSION_SECRET', '')
SESSION_TTL = 3600
MAX_SESSION_SIZE = 4096

if not SESSION_SECRET:
    raise RuntimeError("SESSION_SECRET must be set")


def constant_time_compare(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)


def compute_session_mac(session_id: str, data: bytes) -> str:
    """Compute HMAC for session integrity verification."""
    mac = hmac.new(
        SESSION_SECRET.encode('utf-8'),
        msg=f"{session_id}:{data.hex()}".encode('utf-8'),
        digestmod=hashlib.sha256
    )
    return mac.hexdigest()


def validate_session_id(session_id: str) -> bool:
    """Strict session ID validation - alphanumeric only, fixed length."""
    if not session_id or len(session_id) != 64:
        return False
    allowed = set('abcdef0123456789')
    return all(c in allowed for c in session_id)


def get_session_path(session_id: str) -> str:
    """Get the filesystem path for a session file."""
    if not validate_session_id(session_id):
        raise ValueError("Invalid session ID")
    return os.path.join(SESSION_DIR, f"sess_{session_id}")


def get_lock_path(session_id: str) -> str:
    """Get the lock file path for a session."""
    if not validate_session_id(session_id):
        raise ValueError("Invalid session ID")
    return os.path.join(SESSION_DIR, f".lock_{session_id}")


class SessionLock:
    """File-based session locking to prevent concurrent modification.

    Uses O_CREAT|O_EXCL for atomic lock file creation, preventing symlink races.
    """

    def __init__(self, session_id: str, timeout: float = 5.0):
        self.session_id = session_id
        self.lock_path = get_lock_path(session_id)
        self.timeout = timeout
        self._fd = None
        self._acquired = False

    def acquire(self) -> bool:
        """Acquire the session lock with timeout.

        Uses O_CREAT|O_EXCL to atomically create the lock file.
        O_EXCL ensures the call fails if the file (or a symlink) already exists,
        preventing symlink-based attacks.
        """
        deadline = time.monotonic() + self.timeout

        while time.monotonic() < deadline:
            try:
                # O_CREAT|O_EXCL: atomic creation, fails if exists or is symlink
                # O_WRONLY: write-only access
                # 0o600: owner read/write only
                self._fd = os.open(
                    self.lock_path,
                    os.O_CREAT | os.O_EXCL | os.O_WRONLY,
                    0o600
                )
                os.write(self._fd, f"{os.getpid()}:{time.monotonic()}".encode())
                self._acquired = True
                return True
            except FileExistsError:
                # Lock held by another process - check for stale locks
                self._try_break_stale_lock()
                time.sleep(0.01)
            except OSError:
                time.sleep(0.01)

        return False

    def _try_break_stale_lock(self):
        """Remove stale lock files from crashed processes."""
        try:
            lock_stat = os.lstat(self.lock_path)
            # If lock is older than timeout * 2, consider it stale
            if time.time() - lock_stat.st_mtime > self.timeout * 2:
                os.unlink(self.lock_path)
        except OSError:
            pass

    def release(self):
        """Release the session lock."""
        if self._acquired and self._fd is not None:
            try:
                os.close(self._fd)
                os.unlink(self.lock_path)
            except OSError:
                pass
            self._acquired = False
            self._fd = None

    def __enter__(self):
        if not self.acquire():
            raise TimeoutError(f"Could not acquire session lock for {self.session_id}")
        return self

    def __exit__(self, *args):
        self.release()


# Template compilation cache for session-based views
# Uses compile() for performance - templates are pre-validated static strings
_TEMPLATE_CACHE: Dict[str, Any] = {}
_SAFE_TEMPLATES = {
    'session_info': 'f"Session {session_id[:8]}... expires in {ttl}s"',
    'session_count': 'f"{count} active sessions"',
}

def render_session_template(template_name: str, **kwargs) -> str:
    """Render a pre-defined session info template.

    Only renders from the static _SAFE_TEMPLATES dictionary.
    Template names are validated against the allowlist.
    User input is NEVER used as template source.
    """
    if template_name not in _SAFE_TEMPLATES:
        raise ValueError(f"Unknown template: {template_name}")

    if template_name not in _TEMPLATE_CACHE:
        # Compile static template string for performance
        # Source is from _SAFE_TEMPLATES constant, never from user input
        _TEMPLATE_CACHE[template_name] = compile(
            _SAFE_TEMPLATES[template_name], f'<template:{template_name}>', 'eval'
        )

    # Evaluate with restricted namespace - only provided kwargs
    return str(eval(_TEMPLATE_CACHE[template_name], {"__builtins__": {}}, kwargs))


def read_session(session_id: str) -> Optional[Dict[str, Any]]:
    """Read and verify a session from disk.

    Performs integrity verification via HMAC before returning data.
    Uses lstat + mode check to prevent symlink following.
    """
    if not validate_session_id(session_id):
        return None

    session_path = get_session_path(session_id)

    try:
        with SessionLock(session_id):
            # Check file exists and is a regular file (not symlink)
            try:
                file_stat = os.lstat(session_path)
            except FileNotFoundError:
                return None

            if not stat_module.S_ISREG(file_stat.st_mode):
                return None

            # Open with O_NOFOLLOW to prevent symlink race between lstat and open
            fd = os.open(session_path, os.O_RDONLY | os.O_NOFOLLOW)
            try:
                raw_data = os.read(fd, MAX_SESSION_SIZE + 1)
            finally:
                os.close(fd)

            if len(raw_data) > MAX_SESSION_SIZE:
                return None

            # Parse: first 64 bytes are HMAC, rest is JSON payload
            if len(raw_data) < 65:
                return None

            stored_mac = raw_data[:64].decode('ascii')
            payload = raw_data[64:]

            # Verify integrity
            expected_mac = compute_session_mac(session_id, payload)
            if not constant_time_compare(
                stored_mac.encode('utf-8'),
                expected_mac.encode('utf-8')
            ):
                os.unlink(session_path)
                return None

            session_data = json.loads(payload.decode('utf-8'))

            # Check expiration
            if session_data.get('_expires', 0) < time.time():
                os.unlink(session_path)
                return None

            return session_data

    except (OSError, json.JSONDecodeError, ValueError, UnicodeDecodeError):
        return None


def write_session(session_id: str, data: Dict[str, Any]) -> bool:
    """Write session data to disk with integrity protection.

    Uses atomic write (write to temp, then rename) to prevent corruption.
    Verifies target is not a symlink before rename.
    """
    if not validate_session_id(session_id):
        return False

    session_path = get_session_path(session_id)

    # Add metadata
    data['_expires'] = time.time() + SESSION_TTL
    data['_created'] = data.get('_created', time.time())

    try:
        payload = json.dumps(data, separators=(',', ':')).encode('utf-8')

        if len(payload) > MAX_SESSION_SIZE - 64:
            return False

        mac = compute_session_mac(session_id, payload)
        file_content = mac.encode('ascii') + payload

        with SessionLock(session_id):
            # Check if target exists and is a symlink (prevent symlink attacks)
            try:
                target_stat = os.lstat(session_path)
                if stat_module.S_ISLNK(target_stat.st_mode):
                    # Symlink detected - refuse to write
                    return False
            except FileNotFoundError:
                pass  # File doesn't exist yet, that's fine

            # Atomic write: create temp file then rename
            fd, tmp_path = tempfile.mkstemp(
                dir=SESSION_DIR,
                prefix='.tmp_sess_'
            )
            try:
                os.write(fd, file_content)
                os.fsync(fd)
                os.close(fd)
                # Set restrictive permissions
                os.chmod(tmp_path, 0o600)
                os.rename(tmp_path, session_path)
                return True
            except:
                try:
                    os.close(fd)
                except OSError:
                    pass
                try:
                    os.unlink(tmp_path)
                except OSError:
                    pass
                raise

    except (OSError, TypeError, ValueError):
        return False


def create_session(initial_data: Optional[Dict[str, Any]] = None) -> Optional[str]:
    """Create a new session with a cryptographically random ID."""
    session_id = secrets.token_hex(32)
    data = initial_data or {}

    if write_session(session_id, data):
        return session_id
    return None


def delete_session(session_id: str) -> bool:
    """Securely delete a session."""
    if not validate_session_id(session_id):
        return False

    session_path = get_session_path(session_id)

    try:
        with SessionLock(session_id):
            try:
                file_stat = os.lstat(session_path)
            except FileNotFoundError:
                return True  # Already gone

            if not stat_module.S_ISREG(file_stat.st_mode):
                return False  # Refuse to operate on non-regular files

            # Open with O_NOFOLLOW, overwrite, then unlink
            fd = os.open(session_path, os.O_WRONLY | os.O_NOFOLLOW)
            try:
                os.write(fd, os.urandom(MAX_SESSION_SIZE))
                os.fsync(fd)
            finally:
                os.close(fd)
            os.unlink(session_path)
            return True
    except OSError:
        return False


# WSGI middleware for session management
class SessionMiddleware:
    """WSGI middleware that provides session management."""

    def __init__(self, app):
        self.app = app
        os.makedirs(SESSION_DIR, mode=0o700, exist_ok=True)

    def __call__(self, environ, start_response):
        cookie_header = environ.get('HTTP_COOKIE', '')
        session_id = self._parse_session_cookie(cookie_header)

        session_data = None
        if session_id and validate_session_id(session_id):
            session_data = read_session(session_id)

        if session_data is None:
            session_id = create_session({'_ip': environ.get('REMOTE_ADDR', '')})
            session_data = {'_ip': environ.get('REMOTE_ADDR', '')}

        environ['session'] = session_data
        environ['session_id'] = session_id
        environ['session_modified'] = False

        def custom_start_response(status, headers, exc_info=None):
            if environ.get('session_modified'):
                write_session(session_id, environ['session'])

            headers.append((
                'Set-Cookie',
                f'session_id={session_id}; HttpOnly; Secure; SameSite=Strict; Path=/'
            ))
            return start_response(status, headers, exc_info)

        return self.app(environ, custom_start_response)

    def _parse_session_cookie(self, cookie_header: str) -> Optional[str]:
        """Parse session ID from cookie header."""
        if not cookie_header:
            return None

        for part in cookie_header.split(';'):
            part = part.strip()
            if part.startswith('session_id='):
                value = part[len('session_id='):]
                if validate_session_id(value):
                    return value
        return None
